// The return type of authAndAccess depends on its parameters, c and i.
// 'auto' is a placeholder for the trailing return type specified after '->'.
template<typename Container, typename Index>
auto authAndAccess(Container& c, Index i)
  -> decltype(c[i])
{
  // authenticateUser();
  return c[i];
}

// For a vector of ints, c[i] returns an int&.
// The return type of authAndAccess(v, 0) is deduced as int&.
std::vector<int> v = {10};
int& result = authAndAccess(v, 0);
